public class Main {
    public static void main(String[] args) {
        int[] data = {};
        System.out.println(average(data));
    }

    static int average(int[] nums) {
        int sum = 0;
        for (int n : nums) {
            sum += n;
        }
        return sum / nums.length;
    }
}

